import type { InterviewReview, ReviewQuestion } from "../../db/types";

type ReviewInput = Omit<InterviewReview, "id" | "createdAt" | "updatedAt" | "interviewId">;
export interface InterviewReviewOptions {
  interviewId?: string;
  reviewService?: { getReview(id: string): Promise<InterviewReview | undefined>; saveReview(id: string, input: ReviewInput): Promise<InterviewReview> };
}

function lines(value: string): string[] { return value.split("\n").map((line) => line.trim()).filter(Boolean); }

export function createInterviewReview(documentRef: Document, options: InterviewReviewOptions = {}): HTMLElement {
  const root = documentRef.createElement("section"); root.className = "interview-review"; root.dataset.component = "interview-review"; root.setAttribute("aria-labelledby", "interview-review-title");
  root.innerHTML = `<div class="section-heading"><div><p class="section-label">记录</p><h2 id="interview-review-title">面试复盘</h2></div><span data-review-status role="status" aria-live="polite">请选择面试</span></div><form data-form="review"><label>评分（0 至 5）<input data-review-field="overallRating" type="number" min="0" max="5" step="1" /></label><div class="interview-review__questions"><label>问题（每行一个）<textarea data-review-field="questions" rows="4"></textarea></label><label>回答（按行对应）<textarea data-review-field="answers" rows="4"></textarea></label><label>问题备注（按行对应）<textarea data-review-field="questionNotes" rows="4"></textarea></label></div><label>优势回答<textarea data-review-field="goodAnswers"></textarea></label><label>薄弱回答<textarea data-review-field="weakAnswers"></textarea></label><label>观察信号<textarea data-review-field="observedSignals"></textarea></label><label>薪资讨论<textarea data-review-field="salaryDiscussion"></textarea></label><label>下一步<textarea data-review-field="nextStep"></textarea></label><label>私密备注<textarea data-review-field="privateNote"></textarea></label><div class="interview-review__actions"><button type="submit">保存复盘</button><button type="button" data-action="cancel-review">取消编辑</button></div></form>`;
  const form = root.querySelector<HTMLFormElement>("form")!; const status = root.querySelector<HTMLElement>("[data-review-status]")!; let interviewId = options.interviewId; let lastSaved: InterviewReview | undefined;
  const field = (name: string) => root.querySelector<HTMLInputElement | HTMLTextAreaElement>(`[data-review-field="${name}"]`)!;
  const clear = () => { form.reset(); lastSaved = undefined; status.textContent = interviewId ? "待复盘" : "请选择面试"; };
  const apply = (review: InterviewReview) => { lastSaved = review; field("overallRating").value = review.overallRating === undefined ? "" : String(review.overallRating); field("questions").value = review.questions.map((item) => item.question).join("\n"); field("answers").value = review.questions.map((item) => item.answer ?? "").join("\n"); field("questionNotes").value = review.questions.map((item) => item.note ?? "").join("\n"); for (const name of ["goodAnswers", "weakAnswers", "observedSignals", "salaryDiscussion", "nextStep", "privateNote"] as const) field(name).value = review[name]; status.textContent = "已复盘"; };
  const load = async () => { clear(); if (!interviewId || !options.reviewService) return; const review = await options.reviewService.getReview(interviewId); if (review) apply(review); };
  root.addEventListener("interview-selected", (event) => { interviewId = (event as CustomEvent<string>).detail; void load(); });
  form.addEventListener("submit", async (event) => { event.preventDefault(); if (!interviewId || !options.reviewService) { status.textContent = "请先从日历选择一场面试"; return; } try { const questions = lines(field("questions").value); const answers = field("answers").value.split("\n"); const notes = field("questionNotes").value.split("\n"); const questionItems: ReviewQuestion[] = questions.map((question, index) => ({ question, ...(answers[index]?.trim() ? { answer: answers[index].trim() } : {}), ...(notes[index]?.trim() ? { note: notes[index].trim() } : {}) })); const saved = await options.reviewService.saveReview(interviewId, { overallRating: field("overallRating").value ? Number(field("overallRating").value) : undefined, questions: questionItems, goodAnswers: field("goodAnswers").value, weakAnswers: field("weakAnswers").value, observedSignals: field("observedSignals").value, salaryDiscussion: field("salaryDiscussion").value, nextStep: field("nextStep").value, privateNote: field("privateNote").value }); apply(saved); status.textContent = "复盘已保存 · 已复盘"; root.dispatchEvent(new CustomEvent("review-saved", { detail: saved, bubbles: true })); } catch (error) { status.textContent = error instanceof Error ? error.message : "复盘保存失败"; } });
  root.querySelector('[data-action="cancel-review"]')?.addEventListener("click", () => { if (lastSaved) apply(lastSaved); else clear(); status.textContent = lastSaved ? "已取消编辑，已保存数据未改变" : "已取消编辑，仍待复盘"; });
  void load(); return root;
}
